#### Example 1: Code-First Documentation with Swashbuckle (.NET)

```csharp
// Startup.cs or Program.cs

using Microsoft.OpenApi.Models;
using Swashbuckle.AspNetCore.SwaggerGen;

var builder = WebApplication.CreateBuilder(args);

// Add Swashbuckle services
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v2", new OpenApiInfo
    {
        Title = "Claims Submission API",
        Version = "v2.1.0",
        Description = "Healthcare claim submission and adjudication API",
        Contact = new OpenApiContact
        {
            Name = "Gainwell API Support",
            Email = "api-support@gainwell.com",
            Url = new Uri("https://developer.gainwell.com/support")
        },
        License = new OpenApiLicense
        {
            Name = "Proprietary",
            Url = new Uri("https://gainwell.com/api-terms")
        }
    });

    // Include XML comments for detailed documentation
    var xmlFile = $"{Assembly.GetExecutingAssembly().GetName().Name}.xml";
    var xmlPath = Path.Combine(AppContext.BaseDirectory, xmlFile);
    options.IncludeXmlComments(xmlPath);

    // Add OAuth2 security definition
    options.AddSecurityDefinition("OAuth2", new OpenApiSecurityScheme
    {
        Type = SecuritySchemeType.OAuth2,
        Flows = new OpenApiOAuthFlows
        {
            ClientCredentials = new OpenApiOAuthFlow
            {
                TokenUrl = new Uri("https://auth.gainwell.com/oauth2/token"),
                Scopes = new Dictionary<string, string>
                {
                    { "claims:submit", "Submit medical claims" },
                    { "claims:read", "Read claim status" }
                }
            }
        }
    });

    options.AddSecurityRequirement(new OpenApiSecurityRequirement
    {
        {
            new OpenApiSecurityScheme
            {
                Reference = new OpenApiReference
                {
                    Type = ReferenceType.SecurityScheme,
                    Id = "OAuth2"
                }
            },
            new[] { "claims:submit", "claims:read" }
        }
    });

    // Custom operation filter for examples
    options.OperationFilter<ExampleOperationFilter>();
});

var app = builder.Build();

// Enable middleware for serving generated Swagger JSON
app.UseSwagger(options =>
{
    options.SerializeAsV2 = false;
});

// Enable middleware for serving swagger-ui
app.UseSwaggerUI(options =>
{
    options.SwaggerEndpoint("/swagger/v2/swagger.json", "Claims API v2");
    options.RoutePrefix = "api-docs";
    options.DocumentTitle = "Claims Submission API Documentation";
    options.DisplayRequestDuration();
    options.EnableDeepLinking();
    options.EnableFilter();
});

app.Run();

// Controller with XML documentation comments

